function combos(arr,k,idx=0,p=[],out=[]){if(p.length===k){out.push(p.slice());return} if(arr.length-idx<k-p.length)return; for(let i=idx;i<arr.length;i++){p.push(arr[i]);combos(arr,k,i+1,p,out);p.pop()}}
